"""Generate a generic CRUD frontend from a project's BFF contract."""

from __future__ import annotations

import json
import shutil
from pathlib import Path
from typing import Any

from .sdk import SdkError, generate_sdk, load_schema


def _write_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def _schema_module(schema: list[dict[str, Any]]) -> str:
    body = json.dumps(schema, indent=2, ensure_ascii=False)
    return (
        "/** Generated by core-odoo generate frontend. Do not edit by hand. */\n"
        "export interface FieldSchema {\n"
        "  name: string\n"
        "  type: string\n"
        "  required: boolean\n"
        "}\n\n"
        "export interface ResourceSchema {\n"
        "  name: string\n"
        "  apiKey: string\n"
        "  model: string\n"
        "  operations: string[]\n"
        "  fields: FieldSchema[]\n"
        "}\n\n"
        f"export const resources: ResourceSchema[] = {body}\n"
    )


def generate_frontend(
    project_dir: Path,
    project_name: str,
    *,
    template_dir: Path,
    stage: str = "dev",
    force: bool = False,
) -> dict[str, Any]:
    if not template_dir.is_dir():
        raise SdkError(f"frontend template not found: {template_dir}")
    frontend = project_dir / "frontend"
    custom = (frontend / "package.json").is_file() or (frontend / "src" / "App.tsx").is_file()
    if custom and not force:
        raise SdkError(f"frontend already exists: {frontend} (use --force)")
    if frontend.exists():
        shutil.rmtree(frontend)
    shutil.copytree(template_dir, frontend)

    for path in (frontend / "package.json", frontend / "index.html"):
        if path.is_file():
            path.write_text(
                path.read_text(encoding="utf-8").replace("__PROJECT__", project_name),
                encoding="utf-8",
            )

    schema = load_schema(project_dir, project_name, stage=stage)
    _write_text(frontend / "src" / "schema.generated.ts", _schema_module(schema))
    generate_sdk(
        project_dir,
        project_name,
        stage=stage,
        output=frontend / "src" / "api.generated.ts",
        force=True,
        schema=schema,
    )
    return {
        "path": str(frontend),
        "resources": [resource["name"] for resource in schema],
        "models": [resource["model"] for resource in schema],
    }
